  1→(function () {
  2→  "use strict";
  3→
  4→  // The intake questions per role and category, in form order. Keys match what the
  5→  // server accepts; blank answers are allowed and are what the follow-up round is
  6→  // for. The driver table mirrors app/schemas.DRIVER_INTAKE_QUESTIONS and uses
  7→  // actor-directed keys, so a driver answer can never be read as a rider answer.
  8→  var QUESTIONNAIRES_BY_ROLE = {
  9→    rider: {
 10→      route_deviation: [
 11→        { key: "expected_route", label: "What route did the app show you, and roughly how long was it?", kind: "open" },
 12→        { key: "was_route_agreed", label: "Did you and the driver agree to take a different route?", kind: "yes_no" },
 13→        { key: "asked_driver_to_stop", label: "Did you ask the driver to stop anywhere along the way?", kind: "yes_no" },
 14→        { key: "safety_concern", label: "At any point were you worried for your safety?", kind: "yes_no" }
 15→      ],
 16→      no_show_charge: [
 17→        { key: "where_were_you", label: "Where were you when the trip was meant to start?", kind: "open" },
 18→        { key: "did_driver_contact_you", label: "Did the driver try to contact you?", kind: "yes_no" },
 19→        { key: "safety_concern", label: "At any point were you worried for your safety?", kind: "yes_no" }
 20→      ]
 21→    },
 22→    driver: {
 23→      route_deviation: [
 24→        { key: "route_shown_to_driver", label: "What route did the app show you, and roughly how long was it?", kind: "open" },
 25→        { key: "route_agreed_with_rider", label: "Did you and the rider agree to take a different route?", kind: "yes_no" },
 26→        { key: "rider_requested_stop", label: "Did the rider ask you to stop anywhere along the way?", kind: "yes_no" },
 27→        { key: "safety_concern", label: "At any point were you worried for your safety?", kind: "yes_no" }
 28→      ],
 29→      no_show_charge: [
 30→        { key: "driver_waiting_place", label: "Where did you wait, and for roughly how long?", kind: "open" },
 31→        { key: "driver_contacted_rider", label: "Did you try to call or message the rider?", kind: "yes_no" },
 32→        { key: "safety_concern", label: "At any point were you worried for your safety?", kind: "yes_no" }
 33→      ]
 34→    }
 35→  };
 36→
 37→  var CATEGORIES_BY_ROLE = {
 38→    rider: [
 39→      { id: "route_deviation", label: "My trip went the wrong way" },
 40→      { id: "no_show_charge", label: "I was charged for a trip that did not happen" },
 41→      { id: "property_damage_mess", label: "Property damage or a mess left behind" },
 42→      { id: "safety_incident", label: "A safety incident" },
 43→      { id: "other", label: "Something else" }
 44→    ],
 45→    driver: [
 46→      { id: "route_deviation", label: "A question about the route I took" },
 47→      { id: "no_show_charge", label: "A no-show or waiting fee" },
 48→      { id: "property_damage_mess", label: "A cleaning fee or damage report" },
 49→      { id: "safety_incident", label: "A safety incident" },
 50→      { id: "other", label: "Something else" }
 51→    ]
 52→  };
 53→
 54→  var STATUS_HEADINGS = {
 55→    decided: "We have made a decision",
 56→    under_review: "Your case is still under review",
 57→    passed_to_support: "Your report has been passed to our support team",
 58→    needs_info: "We need a little more information"
 59→  };
 60→
 61→  var state = {
 62→    category: null,
 63→    tripId: null,
 64→    trips: [],
 65→    runId: null
