 67→
 68→  var stepCategory = document.getElementById("step-category");
 69→  var stepTrip = document.getElementById("step-trip");
 70→  var stepDetails = document.getElementById("step-details");
 71→  var outcomePanel = document.getElementById("outcome");
 72→  var categoryOptions = document.getElementById("category-options");
 73→  var tripOptions = document.getElementById("trip-options");
 74→  var questionList = document.getElementById("question-list");
 75→  var questionBoxes = document.getElementById("question-boxes");
 76→  var outcomeTitle = document.getElementById("outcome-title");
 77→  var outcomeReference = document.getElementById("outcome-reference");
 78→  var outcomeMessage = document.getElementById("outcome-message");
 79→  var outcomeQuestions = document.getElementById("outcome-questions");
 80→  var outcomeStatus = document.getElementById("outcome-status");
