 82→  function element(tag, className, text) {
 83→    var node = document.createElement(tag);
 84→    if (className) {
 85→      node.className = className;
 86→    }
 87→    if (text !== undefined && text !== null) {
 88→      node.textContent = String(text);
 89→    }
 90→    return node;
 91→  }
 92→
 93→  function showError(id, message) {
 94→    var node = document.getElementById(id);
 95→    node.textContent = message;
 96→    node.hidden = false;
 97→  }
 98→
 99→  function clearError(id) {
100→    var node = document.getElementById(id);
101→    node.textContent = "";
102→    node.hidden = true;
103→  }
104→
105→  function show(node) {
106→    node.hidden = false;
107→  }
108→
109→  function hide(node) {
110→    node.hidden = true;
111→  }
112→
113→  function request(method, path, body) {
114→    var options = { method: method };
115→    if (body !== undefined) {
116→      options.headers = { "Content-Type": "application/json" };
117→      options.body = JSON.stringify(body);
118→    }
119→    return fetch(path, options).then(function (response) {
120→      return response.json().then(function (payload) {
121→        if (!response.ok) {
122→          var reason = payload && payload.error ? payload.error : "Something went wrong. Please try again.";
123→          throw new Error(reason);
124→        }
125→        return payload;
126→      });
127→    });
128→  }
129→
130→  // ------------------------------------------------------------- page role
131→
132→  // The shell's own marker selects the questionnaire and the category copy. A
133→  // missing marker is the original rider shell; any other explicit value refuses
134→  // the whole page. This is demo copy selection, not authentication: the role is
135→  // never read from the URL, the document body or the fixed driver account.
136→  var formSteps = document.getElementById("form-steps");
137→  var role = formSteps.getAttribute("data-filed-by");
138→  if (role === null) {
139→    role = "rider";
140→  }
141→  var QUESTIONNAIRES = QUESTIONNAIRES_BY_ROLE[role];
142→  var CATEGORIES = CATEGORIES_BY_ROLE[role];
143→  if (role !== "rider" && role !== "driver") {
144→    showError("category-error",
145→      "This filing page could not be loaded. Please return to the help page and try again.");
146→    return;
147→  }
148→
149→  // ------------------------------------------------------------- step one
150→
151→  CATEGORIES.forEach(function (category) {
152→    var card = element("button", "option-card", category.label);
153→    card.type = "button";
154→    card.addEventListener("click", function () {
155→      state.category = category.id;
156→      Array.prototype.forEach.call(categoryOptions.children, function (child) {
157→        child.classList.remove("selected");
158→      });
159→      card.classList.add("selected");
160→      document.getElementById("category-next").disabled = false;
161→      // Changing the category resets everything downstream (R3 page side): the trip
162→      // list belongs to the category, so a trip picked for one category must never
163→      // survive a switch to another.
164→      state.tripId = null;
165→      while (tripOptions.firstChild) {
166→        tripOptions.removeChild(tripOptions.firstChild);
167→      }
168→      document.getElementById("trip-next").disabled = true;
169→      clearError("trip-error");
170→      clearError("details-error");
171→      hide(stepTrip);
172→      hide(stepDetails);
173→    });
174→    categoryOptions.appendChild(card);
175→  });
176→
177→  document.getElementById("category-next").addEventListener("click", function () {
178→    clearError("category-error");
179→    hide(stepCategory);
180→    show(stepTrip);
181→    hide(stepDetails);
182→    loadTrips();
183→  });
184→
185→  // ------------------------------------------------------------- step two
186→
187→  // W30: bring the whole trip card on screen once the list has rendered. The card
188→  // is at most one screen tall, so aligning its top shows the Continue/Back bar
189→  // too. A response that arrives after the party pressed Back must not move the
190→  // page, so a hidden trip step is left alone.
191→  function landTripCard() {
192→    if (stepTrip.hidden) {
193→      return;
194→    }
195→    stepTrip.scrollIntoView({ block: "start" });
196→  }
197→
198→  function loadTrips() {
199→    var boxes = tripOptions;
200→    while (boxes.firstChild) {
201→      boxes.removeChild(boxes.firstChild);
202→    }
203→    state.tripId = null;
204→    document.getElementById("trip-next").disabled = true;
205→    boxes.appendChild(element("p", "loading", "Loading trips…"));
206→    request("GET", "/api/trips?category=" + encodeURIComponent(state.category))
207→      .then(function (payload) {
208→        while (boxes.firstChild) {
209→          boxes.removeChild(boxes.firstChild);
210→        }
211→        state.trips = Array.isArray(payload.trips) ? payload.trips : [];
212→        if (state.trips.length === 0) {
213→          boxes.appendChild(element("p", "hint", "No trips are available in the sample dataset."));
214→          landTripCard();
215→          return;
216→        }
217→        state.trips.forEach(function (trip) {
218→          var meta = [trip.date, trip.kind_label].filter(Boolean).join(" · ");
219→          var lines = [
220→            element("strong", null, trip.label),
221→            element("span", "trip-meta", meta)
222→          ];
223→          var charge = "";
224→          if (trip.fare_sgd !== null && trip.fare_sgd !== undefined) {
225→            charge = " · SGD " + Number(trip.fare_sgd).toFixed(2)
226→              + (trip.charge_label ? " " + trip.charge_label : "");
227→          }
228→          var detail = element("span", "trip-meta", "");
229→          detail.textContent = "Trip " + trip.trip_id + charge;
230→          var card = element("button", "option-card trip-card");
231→          card.type = "button";
232→          lines.forEach(function (line) { card.appendChild(line); });
233→          card.appendChild(detail);
234→          card.addEventListener("click", function () {
235→            state.tripId = trip.trip_id;
236→            Array.prototype.forEach.call(boxes.children, function (child) {
237→              child.classList.remove("selected");
238→            });
239→            card.classList.add("selected");
240→            document.getElementById("trip-next").disabled = false;
241→          });
242→          boxes.appendChild(card);
243→        });
244→        landTripCard();
245→      })
246→      .catch(function (error) {
247→        while (boxes.firstChild) {
248→          boxes.removeChild(boxes.firstChild);
249→        }
250→        showError("trip-error", error.message);
251→      });
252→  }
253→
254→  document.getElementById("trip-back").addEventListener("click", function () {
255→    show(stepCategory);
256→    hide(stepTrip);
257→    stepCategory.scrollIntoView({ block: "start" });
258→  });
259→
260→  document.getElementById("trip-next").addEventListener("click", function () {
261→    clearError("trip-error");
262→    hide(stepTrip);
263→    buildQuestions();
264→    show(stepDetails);
265→    window.scrollTo(0, 0);
266→  });
