268→  // --------------------------------------------------------- step three
269→
270→  function buildChoiceQuestion(question) {
271→    var field = element("div", "field");
272→    var label = element("label", null, question.label);
273→    // The choices container is a div, so a <label for> cannot point at it. The
274→    // question text reaches assistive tech via role="group" + aria-labelledby.
275→    label.id = "label-" + question.key;
276→    var choices = element("div", "choice-options");
277→    choices.id = "answer-" + question.key;
278→    choices.role = "group";
279→    choices.setAttribute("aria-labelledby", "label-" + question.key);
280→    var elaborate = element("textarea", "answer-input elaborate");
281→    elaborate.rows = 2;
282→    elaborate.setAttribute("data-elaborate-for", question.key);
283→    elaborate.placeholder = "Tell us more (optional)";
284→    elaborate.setAttribute("aria-label", "Tell us more: " + question.label);
285→    elaborate.hidden = true;
286→
287→    ["Yes", "No"].forEach(function (choice) {
288→      var button = element("button", "choice-button", choice);
289→      button.type = "button";
290→      button.setAttribute("data-choice", choice);
291→      button.setAttribute("aria-pressed", "false");
292→      button.dataset.questionKey = question.key;
293→      button.addEventListener("click", function () {
294→        if (!button.classList.contains("selected")) {
295→          elaborate.value = "";
296→        }
297→        Array.prototype.forEach.call(choices.children, function (sibling) {
298→          sibling.classList.remove("selected");
299→          sibling.setAttribute("aria-pressed", "false");
300→        });
301→        button.classList.add("selected");
302→        button.setAttribute("aria-pressed", "true");
303→        show(elaborate);
304→      });
305→      choices.appendChild(button);
306→    });
307→
308→    field.appendChild(label);
309→    field.appendChild(choices);
310→    field.appendChild(elaborate);
311→    return field;
312→  }
313→
314→  function buildQuestions() {
315→    while (questionList.firstChild) {
316→      questionList.removeChild(questionList.firstChild);
317→    }
318→    var questions = QUESTIONNAIRES[state.category] || [];
319→    questions.forEach(function (question) {
320→      if (question.kind === "yes_no") {
321→        questionList.appendChild(buildChoiceQuestion(question));
322→      } else if (question.kind === "open") {
323→        var field = element("div", "field");
324→        var label = element("label", null, question.label);
325→        label.htmlFor = "answer-" + question.key;
326→        var input = element("textarea", "answer-input");
327→        input.id = "answer-" + question.key;
328→        input.rows = 2;
329→        input.dataset.questionKey = question.key;
330→        field.appendChild(label);
331→        field.appendChild(input);
332→        questionList.appendChild(field);
333→      }
334→    });
335→  }
336→
337→  document.getElementById("details-back").addEventListener("click", function () {
338→    hide(stepDetails);
339→    show(stepTrip);
340→    loadTrips();
341→  });
342→
343→  document.getElementById("details-form").addEventListener("submit", function (event) {
344→    event.preventDefault();
345→    clearError("details-error");
346→    var description = document.getElementById("description").value;
347→    if (!description.trim()) {
348→      showError("details-error", "Please tell us what happened before sending.");
349→      return;
350→    }
351→    var amountText = document.getElementById("claim-amount").value.trim();
352→    var amount = null;
353→    if (amountText !== "") {
354→      amount = Number(amountText);
355→      if (!isFinite(amount) || amount < 0 || amount > 500) {
356→        showError("details-error", "The amount must be between 0 and 500 SGD.");
357→        return;
358→      }
359→    }
360→    var answers = {};
361→    (QUESTIONNAIRES[state.category] || []).forEach(function (question) {
362→      if (question.kind === "yes_no") {
363→        var selected = questionList.querySelector(
364→          '.choice-button.selected[data-question-key="' + question.key + '"]'
365→        );
366→        var elaborate = questionList.querySelector(
367→          'textarea[data-elaborate-for="' + question.key + '"]'
368→        );
369→        var choice = selected ? selected.dataset.choice : "";
370→        var elaboration = elaborate ? elaborate.value.trim() : "";
371→        answers[question.key] = choice
372→          ? (elaboration ? choice + " - " + elaboration : choice)
373→          : "";
374→      } else if (question.kind === "open") {
375→        var input = questionList.querySelector(
376→          'textarea[data-question-key="' + question.key + '"]'
377→        );
378→        answers[question.key] = input ? input.value : "";
379→      }
380→    });
381→
382→    var submit = document.getElementById("details-submit");
383→    submit.disabled = true;
384→    request("POST", "/api/disputes", {
385→      category: state.category,
386→      filed_by: role,
387→      trip_id: state.tripId,
388→      description: description,
389→      claim_amount_sgd: amount,
390→      answers: answers
391→    })
392→      .then(function (view) {
393→        renderOutcome(view);
394→      })
395→      .catch(function (error) {
396→        submit.disabled = false;
397→        showError("details-error", error.message);
398→      });
399→  });
400→
401→  // ------------------------------------------------------------- outcome
402→
403→  function renderOutcome(view) {
404→    hide(document.getElementById("form-steps"));
405→    show(outcomePanel);
406→    state.runId = view.run_id;
407→    outcomeTitle.textContent = STATUS_HEADINGS[view.status] || "Your dispute has been received";
408→    outcomeReference.textContent = view.dispute_id;
409→    outcomeMessage.textContent = view.message;
410→    hide(outcomeStatus);
411→    buildAnswerBoxes(view);
412→    window.scrollTo(0, 0);
413→  }
414→
415→  function buildAnswerBoxes(view) {
416→    while (questionBoxes.firstChild) {
417→      questionBoxes.removeChild(questionBoxes.firstChild);
418→    }
419→    var questions = Array.isArray(view.questions) ? view.questions : [];
420→    if (view.status !== "needs_info" || questions.length === 0) {
421→      hide(outcomeQuestions);
422→      return;
423→    }
424→    show(outcomeQuestions);
425→    questions.forEach(function (question, index) {
426→      var field = element("div", "field");
427→      var label = element("label", null, question);
428→      label.htmlFor = "reply-" + index;
429→      var input = element("textarea", "answer-input");
430→      input.id = "reply-" + index;
431→      input.rows = 2;
432→      // A round-two question the party has nothing to add to still needs an answer:
433→      // one click fills this box with the same sentence the run harness uses, so the
434→      // form can be completed without the party inventing words.
435→      var nothingMore = element("button", "nothing-more", "I have nothing more to add");
436→      nothingMore.type = "button";
437→      nothingMore.addEventListener("click", function () {
438→        input.value = "I have nothing more to add";
439→      });
440→      field.appendChild(label);
441→      field.appendChild(input);
442→      field.appendChild(nothingMore);
443→      questionBoxes.appendChild(field);
444→    });
445→  }
446→
447→  document.getElementById("answers-submit").addEventListener("click", function () {
448→    clearError("answers-error");
449→    var replies = [];
450→    var complete = true;
451→    Array.prototype.forEach.call(questionBoxes.querySelectorAll("textarea"), function (input) {
452→      var label = questionBoxes.querySelector('label[for="' + input.id + '"]');
453→      replies.push({ question: label ? label.textContent : "", answer: input.value });
454→      if (!input.value.trim()) {
455→        complete = false;
456→      }
457→    });
458→    if (!complete) {
459→      showError("answers-error", "Please answer each question before sending.");
460→      return;
461→    }
462→    var submit = document.getElementById("answers-submit");
463→    submit.disabled = true;
464→    outcomeStatus.textContent = "Sending your answers…";
465→    show(outcomeStatus);
466→    request("POST", "/api/disputes/" + encodeURIComponent(state.runId) + "/answers", {
467→      answers: replies
468→    })
469→      .then(function (view) {
470→        renderOutcome(view);
471→      })
472→      .catch(function (error) {
473→        submit.disabled = false;
474→        hide(outcomeStatus);
475→        showError("answers-error", error.message);
476→      });
477→  });
478→}());
