  1→/* W30 review repair: deterministic real-browser race and error-card checks.
  2→ * Run with PUPPETEER_MODULE / BROWSER_EXECUTABLE, BASE_URL and OUTPUT_JSON.
  3→ * No submissions, backend writes, or timing races. Each held request is released explicitly.
  4→ */
  5→const assert = require('node:assert/strict');
  6→const fs = require('node:fs');
  7→const puppeteer = require(process.env.PUPPETEER_MODULE || 'puppeteer');
  8→const [base, output] = process.argv.slice(2);
  9→const report = {passed:false, cases:[], errors:[]};
 10→(async()=>{
 11→  const browser = await puppeteer.launch({headless:true,
 12→    executablePath:process.env.BROWSER_EXECUTABLE, args:['--no-sandbox']});
 13→  try {
 14→    for (const file of ['index.html','driver-filing.html']) {
 15→      for (const stale of ['success','failure']) for (const state of ['pending','settled']) {
 16→        const page = await browser.newPage();
 17→        page.on('pageerror', e=>report.errors.push(String(e)));
 18→        await page.setViewport({width:390,height:844});
 19→        await page.setRequestInterception(true);
 20→        const held = [];
 21→        page.on('request', r=>r.url().includes('/api/trips') ? held.push(r) : r.continue());
 22→        await page.goto(base+'/party/'+file,{waitUntil:'domcontentloaded'});
 23→        // Record landing calls as well as the actual browser geometry.
 24→        await page.evaluate(()=>{
 25→          window.tripLandings=[];
 26→          const original=Element.prototype.scrollIntoView;
 27→          Element.prototype.scrollIntoView=function(o){
 28→            if(this.id==='step-trip') window.tripLandings.push(o.block);
 29→            return original.call(this,o);
 30→          };
 31→        });
 32→        await page.waitForSelector('#category-options .option-card');
 33→        await page.click('#category-options .option-card:first-child');
 34→        await page.click('#category-next');
 35→        const waitHeld = async n=>{
 36→          const start=Date.now();
 37→          while(held.length<n){assert.ok(Date.now()-start<5000,'request was not issued'); await new Promise(r=>setTimeout(r,10));}
 38→        };
 39→        await waitHeld(1);
 40→        await page.click('#trip-back');
 41→        await page.click('#category-options .option-card:nth-child(2)');
 42→        await page.click('#category-next');
 43→        await waitHeld(2);
 44→        const respond = async (index, bad=false)=>{
 45→          const r=held[index];
 46→          const body=bad ? {error:'old failure'} : {trips:Array.from({length:index===0?2:5},(_,i)=>({
 47→            trip_id:(index===0?'OLD-':'NEW-')+i,label:(index===0?'Old trip ':'New trip ')+i,date:'2026',kind_label:'Ride',fare_sgd:6.61}))};
 48→          const finished=page.waitForResponse(response=>response.url()===r.url());
 49→          await r.respond({status:bad?500:200,contentType:'application/json',body:JSON.stringify(body)});
 50→          const response=await finished; await response.text();
 51→          // Give the fetch promise and render continuation two animation frames to settle.
 52→          await page.evaluate(()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve))));
 53→        };
 54→        if(state==='settled'){
 55→          await respond(1);
 56→          await page.waitForFunction(()=>document.querySelectorAll('#trip-options .trip-card').length===5);
 57→          await page.click('#trip-options .trip-card:first-child');
 58→        }
 59→        const snapshot = ()=>page.evaluate(()=>({
 60→          text:document.getElementById('trip-options').textContent,
 61→          selected:document.querySelector('#trip-options .selected')?.textContent || null,
 62→          nextDisabled:document.getElementById('trip-next').disabled,
 63→          error:document.getElementById('trip-error').textContent,
 64→          errorHidden:document.getElementById('trip-error').hidden,
 65→          landings:window.tripLandings.slice(), scrollY
 66→        }));
 67→        const before=await snapshot();
 68→        await respond(0,stale==='failure');
 69→        const after=await snapshot();
 70→        assert.deepEqual(after,before,'superseded '+stale+' must not change the '+state+' view');
 71→        if(state==='pending'){
 72→          await respond(1);
 73→          await page.waitForFunction(()=>document.querySelectorAll('#trip-options .trip-card').length===5);
 74→          assert.equal((await snapshot()).landings.length,1);
 75→        }
 76→        report.cases.push({file,stale,state,before,after});
 77→        await page.close();
 78→      }
 79→      // The current failure must show the heading, error and Back after Continue
 80→      // from a scrolled category card, including the short landscape viewport.
 81→      for (const [width,height] of [[390,844],[800,320]]) {
 82→        const page=await browser.newPage();
 83→        await page.setViewport({width,height});
