383→/* The trip list scrolls inside itself, so the Continue/Back bar stays in normal
384→   flow directly under it and never over an option. Its padding keeps a lifted or
385→   selected card clear of the region edge, and the equal negative margin keeps the
386→   cards aligned with the card's content box. The background is two token-coloured
387→   layers: a card-coloured cover that scrolls with the content and hides the fade
388→   once the list is at its end, and a fade pinned to the region's bottom edge while
389→   more trips are below. */
390→#step-trip #trip-options {
391→  flex: 1 1 auto;
392→  min-height: 0;
393→  overflow-y: auto;
394→  overscroll-behavior: contain;
395→  padding: 0.75rem;
396→  margin: -0.75rem;
397→  background:
398→    linear-gradient(var(--card), var(--card)) bottom / 100% 2.5rem local no-repeat,
399→    linear-gradient(to top, var(--line), transparent) bottom / 100% 2.5rem scroll no-repeat;
400→}
