  1→/* Real-browser W30 contract: the trip step is a viewport-fit card with its own scroll region.
  2→ * Requires Puppeteer and a live mock server (python3 -m app.server style; no app writes).
  3→ *   PUPPETEER_MODULE=/path/to/puppeteer BROWSER_EXECUTABLE=/path/to/browser \
  4→ *     node tests/browser/w30_trip_scroll.cjs BASE_URL OUTPUT_JSON
  5→ * Battery hooks: W30_CSS_OVERRIDE / W30_JS_OVERRIDE serve a mutated party.css / party.js.
  6→ *
  7→ * Every viewport, including short landscape, must keep Back/Continue at the visible screen's
  8→ * bottom on entry, list scrolling and live resize. No two-trip floor/page-scroll fallback.
  9→ * Every view: one visible step at each stage, no horizontal overflow, a list that scrolls
 10→ * internally, an action bar that follows the cards, no clipped hover/selected card, a fade
 11→ * that shows only while more trips are below (read from real pixels), and a keyboard order
 12→ * of last card -> Back -> Continue.
 13→ */
 14→const assert = require('node:assert/strict');
 15→const fs = require('fs');
 16→const path = require('path');
 17→const puppeteer = require(process.env.PUPPETEER_MODULE || 'puppeteer');
 18→const base = process.argv[2] || 'http://127.0.0.1:55817';
 19→const output = process.argv[3];
 20→if (!output) throw new Error('OUTPUT_JSON is required');
 21→fs.mkdirSync(path.dirname(output), { recursive: true });
 22→const viewports = [[360, 740], [390, 844], [600, 900], [1200, 600], [1200, 700], [1200, 900],
 23→  [1200, 500], [360, 480], [800, 320]];
 24→const report = { views: [], errors: [], passed: false };
 25→const GAP = 16;
 26→
 27→(async () => {
 28→  const browser = await puppeteer.launch({ headless: true,
 29→    ...(process.env.BROWSER_EXECUTABLE ? { executablePath: process.env.BROWSER_EXECUTABLE } : {}),
 30→    args: ['--no-sandbox'] });
 31→  try {
 32→    for (const file of ['index.html', 'driver-filing.html']) {
 33→      for (const [width, height] of viewports) {
 34→        const tall = height >= 600;
 35→        const page = await browser.newPage();
 36→        const view = { file, width, height, tall, stages: [] };
 37→        report.views.push(view);
 38→        page.on('pageerror', e => report.errors.push(String(e)));
 39→        await page.setViewport({ width, height });
 40→        if (process.env.W30_CSS_OVERRIDE || process.env.W30_JS_OVERRIDE) {
 41→          await page.setRequestInterception(true);
 42→          page.on('request', r => {
 43→            if (process.env.W30_CSS_OVERRIDE && r.url().endsWith('/party/party.css')) {
 44→              return r.respond({ status: 200, contentType: 'text/css', body: fs.readFileSync(process.env.W30_CSS_OVERRIDE, 'utf8') });
 45→            }
 46→            if (process.env.W30_JS_OVERRIDE && r.url().endsWith('/party/party.js')) {
 47→              return r.respond({ status: 200, contentType: 'application/javascript', body: fs.readFileSync(process.env.W30_JS_OVERRIDE, 'utf8') });
 48→            }
 49→            return r.continue();
 50→          });
 51→        }
 52→        await page.goto(base + '/party/' + file, { waitUntil: 'networkidle0' });
 53→        await page.evaluate(() => document.fonts.ready);
 54→        const visible = () => page.evaluate(() =>
 55→          [...document.querySelectorAll('#form-steps > .step')].filter(e => !e.hidden).map(e => e.id));
 56→        const settle = () => new Promise(r => setTimeout(r, 250));
 57→
 58→        // Step 1 -> 2 on the second category (the route/no-show lists differ in height).
 59→        await page.click('#category-options .option-card:nth-child(1)');
 60→        await page.click('#category-next');
 61→        await page.waitForSelector('#trip-options .trip-card');
 62→        await settle();
 63→        assert.deepEqual(await visible(), ['step-trip'], 'only the trip step is visible');
 64→
 65→        const geo = () => page.evaluate(() => {
 66→          const rect = e => { const r = e.getBoundingClientRect(); return { top: r.top, bottom: r.bottom, left: r.left, right: r.right, height: r.height }; };
 67→          const card = document.getElementById('step-trip');
 68→          const list = document.getElementById('trip-options');
 69→          const bar = card.querySelector('.step-actions');
 70→          const cards = [...list.querySelectorAll('.trip-card')];
 71→          const hit = el => { const r = el.getBoundingClientRect(); const h = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2); return !!h && (h === el || el.contains(h)); };
 72→          const cs = getComputedStyle(list);
 73→          return { vh: innerHeight, vw: innerWidth, scrollY: scrollY, card: rect(card), list: rect(list), bar: rect(bar),
 74→            back: rect(document.getElementById('trip-back')), next: rect(document.getElementById('trip-next')),
 75→            backHit: hit(document.getElementById('trip-back')), nextHit: document.getElementById('trip-next').disabled ? null : hit(document.getElementById('trip-next')),
 76→            scrollable: list.scrollHeight > list.clientHeight + 1, listClient: list.clientHeight,
 77→            hScroll: list.scrollWidth > list.clientWidth + 1, pageOverflow: document.documentElement.scrollWidth - innerWidth,
 78→            tallestCard: Math.max(...cards.map(c => c.getBoundingClientRect().height)), count: cards.length,
 79→            visibleCardsHit: cards.filter(c => { const r = c.getBoundingClientRect(), l = list.getBoundingClientRect(); return r.top >= l.top && r.bottom <= l.bottom && r.top >= 0 && r.bottom <= innerHeight; }).every(c => hit(c)),
 80→            overscroll: cs.overscrollBehaviorY, overflowY: cs.overflowY, bgImage: cs.backgroundImage, bgAttach: cs.backgroundAttachment };
 81→        });
 82→        const g = await geo();
 83→        view.stages.push({ stage: 'trip-entered', ...g });
 84→        assert.ok(g.pageOverflow <= 0, 'no horizontal page overflow');
 85→        assert.ok(g.card.top >= 0, 'the card heading is on screen');
 86→        assert.equal(g.scrollable, true, 'the list scrolls inside its own region');
 87→        assert.equal(g.hScroll, false, 'no horizontal scroll inside the region');
 88→        assert.equal(g.overflowY, 'auto');
 89→        assert.equal(g.overscroll, 'contain');
 90→        assert.ok(g.list.bottom <= g.bar.top + 0.5, 'the bar follows the list');
 91→        assert.equal(g.visibleCardsHit, true, 'every fully visible trip is the element at its own centre');
 92→        assert.ok(g.card.bottom >= g.bar.bottom - 0.5, 'the bar stays inside the card');
 93→        const assertPinned = p => {
 94→          assert.ok(p.card.top >= GAP - 1, 'breathing room above the card: ' + p.card.top);
 95→          assert.ok(p.card.bottom <= p.vh - GAP + 1, 'whole trip card fits screen: ' + p.card.bottom + ' of ' + p.vh);
 96→          assert.ok(p.back.top >= 0 && p.next.top >= 0 && p.next.bottom <= p.vh && p.back.bottom <= p.vh,
 97→            'Continue/Back visible without scrolling the page');
 98→          assert.ok(p.vh - p.back.bottom <= 80 && p.vh - p.next.bottom <= 80, 'buttons anchored near viewport bottom');
 99→          assert.equal(p.backHit, true, 'Back is the element at its own centre');
100→          assert.ok(p.list.height > 24 && p.list.bottom <= p.bar.top + 0.5, 'list fits above actions');
101→        };
102→        assertPinned(g);
103→
104→        // Resize the SAME loaded page, not a fresh navigation that can hide the regression.
105→        for (const h of [320, 480, 700, 900, height]) {
106→          await page.setViewport({ width, height: h });
107→          await settle();
108→          const resized = await geo();
109→          assertPinned(resized);
110→          assert.equal(await page.$$eval('#trip-options .trip-card', e => e.length), g.count, 'resize preserves trips');
111→          view.stages.push({ stage: 'live-resize', ...resized });
112→        }
113→
114→        // Scroll the region itself; the page must not move, the last card must end inside it.
115→        const before = await page.evaluate(() => scrollY);
116→        await page.evaluate(() => { const l = document.getElementById('trip-options'); l.scrollTop = l.scrollHeight; });
117→        await settle();
118→        const end = await page.evaluate(() => {
119→          const l = document.getElementById('trip-options'); const last = l.lastElementChild.getBoundingClientRect(); const lr = l.getBoundingClientRect();
120→          return { lastInside: last.bottom <= lr.bottom + 0.5, scrollY: scrollY };
121→        });
122→        assert.equal(end.lastInside, true, 'the last trip can be scrolled fully into the region');
123→        assert.equal(end.scrollY, before, 'scrolling the list does not scroll the page');
124→        view.stages.push({ stage: 'list-scrolled-to-end', ...end });
125→
126→        // Fade: real pixels in the region's left gutter (no card paints there), just above its
127→        // bottom edge. At the top of the list the fade tints it; at the end it is the card white.
128→        async function gutterPixel() {
129→          // Park the pointer away: a hovered card paints a shadow into the gutter being sampled.
130→          await page.mouse.move(0, 0);
131→          await settle();
132→          // A screenshot clip is in DOCUMENT coordinates, so add the page scroll offset.
133→          const place = () => page.evaluate(() => { const r = document.getElementById('trip-options').getBoundingClientRect(); return { x: r.left + 4 + scrollX, y: r.bottom - 4 + scrollY, vy: r.bottom - 4 }; });
134→          let spot = await place();
135→          if (spot.vy < 0 || spot.vy >= (await page.evaluate(() => innerHeight))) {
