  1→/* Real-browser W30 contract: the trip step is a viewport-fit card with its own scroll region.
  2→ * Requires Puppeteer and a live mock server (python3 -m app.server style; no app writes).
  3→ *   PUPPETEER_MODULE=/path/to/puppeteer BROWSER_EXECUTABLE=/path/to/browser \
  4→ *     node tests/browser/w30_trip_scroll.cjs BASE_URL OUTPUT_JSON
  5→ * Battery hooks: W30_CSS_OVERRIDE / W30_JS_OVERRIDE serve a mutated party.css / party.js.
  6→ *
  7→ * Every viewport, including short landscape, must keep Back/Continue at the visible screen's
  8→ * bottom on entry, list scrolling and live resize. No two-trip floor/page-scroll fallback.
  9→ * Every view: one visible step at each stage, no horizontal overflow, a list that scrolls
 10→ * internally, an action bar that follows the cards, no clipped hover/selected card, a fade
 11→ * that shows only while more trips are below (read from real pixels), and a keyboard order
 12→ * of last card -> Back -> Continue.
 13→ */
 14→const assert = require('node:assert/strict');
 15→const fs = require('fs');
 16→const path = require('path');
 17→const puppeteer = require(process.env.PUPPETEER_MODULE || 'puppeteer');
 18→const base = process.argv[2] || 'http://127.0.0.1:55817';
 19→const output = process.argv[3];
 20→if (!output) throw new Error('OUTPUT_JSON is required');
